mapper.insert:
insert into PBC_PRD_BASEINFO_END_SUB_DAT (REGIST_SEQNO, PBC_PROD_ID, MDATE, CCY, PROFIT, PROFIT_CNY, CUSTOM_PROFIT, CUSTOM_PROFIT_CNY, CUS_YEAR_YIELD, SEND_STATUS, SUBMIT_TIME, SUBMIT_FEEDBACK_STATUS, SUMIT_SEQ, STATUS_DATE, PBC_SUBMIT_DEADLINE, SUBMIT_DEADLINE, STATUS, CREATE_USER, ORG_CODE, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME,PROD_ID,DAT_ZIP_CODE) select REGIST_SEQNO, PBC_PROD_ID, MDATE, CCY, PROFIT, PROFIT_CNY, CUSTOM_PROFIT, CUSTOM_PROFIT_CNY, CUS_YEAR_YIELD, SEND_STATUS, SUBMIT_TIME, SUBMIT_FEEDBACK_STATUS, SUMIT_SEQ, STATUS_DATE, PBC_SUBMIT_DEADLINE, SUBMIT_DEADLINE, STATUS, CREATE_USER, ORG_CODE, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME,PROD_ID,DAT_ZIP_CODE from (
select f_guid() REGIST_SEQNO, #{item.pbcProdId,jdbcType=VARCHAR} PBC_PROD_ID, #{item.mdate,jdbcType=TIMESTAMP} MDATE, #{item.ccy,jdbcType=CHAR} CCY, #{item.profit,jdbcType=DECIMAL} PROFIT, #{item.profitCny,jdbcType=DECIMAL} PROFIT_CNY, #{item.customProfit,jdbcType=DECIMAL} CUSTOM_PROFIT, #{item.customProfitCny,jdbcType=DECIMAL} CUSTOM_PROFIT_CNY, #{item.cusYearYield,jdbcType=DECIMAL} CUS_YEAR_YIELD, #{item.sendStatus,jdbcType=VARCHAR} SEND_STATUS, #{item.submitTime,jdbcType=TIMESTAMP} SUBMIT_TIME, #{item.submitFeedbackStatus,jdbcType=VARCHAR} SUBMIT_FEEDBACK_STATUS, #{item.sumitSeq,jdbcType=VARCHAR} SUMIT_SEQ, now() STATUS_DATE, #{item.pbcSubmitDeadline,jdbcType=TIMESTAMP} PBC_SUBMIT_DEADLINE, #{item.submitDeadline,jdbcType=TIMESTAMP} SUBMIT_DEADLINE, #{item.status,jdbcType=VARCHAR} STATUS, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.updateTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.createTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.datZipCode,jdbcType=VARCHAR} DAT_ZIP_CODE from dual
)as tt

mapper.select:
select
a.REGIST_SEQNO registSeqno,
a.PBC_PROD_ID PBC_PROD_ID,
a.MDATE mdate,
a.CCY ccy,
a.PROFIT profit,
a.PROFIT_CNY profitCny,
a.CUSTOM_PROFIT customProfit,
a.CUSTOM_PROFIT_CNY customProfitCny,
a.CUS_YEAR_YIELD cusYearYield,
a.SEND_STATUS sendStatus,
a.SUBMIT_TIME submitTime,
a.SUBMIT_FEEDBACK_STATUS submitFeedbackStatus,
a.SUMIT_SEQ sumitSeq,
a.STATUS_DATE statusDate,
a.PBC_SUBMIT_DEADLINE pbcSubmitDeadline,
a.SUBMIT_DEADLINE submitDeadline,
a.STATUS status,
a.CREATE_USER createUser,
a.ORG_CODE orgCode,
a.CREATE_DEPT createDept,
a.CREATE_TIME createTime,
a.UPDATE_USER updateUser,
a.UPDATE_TIME updateTime,
b.PROD_ID prodId,
b.OPERATE_MODE operateMode,
b.IVSTORIENTATION ivstorientation,
b.VDATE vdate,
t2.PBC_CODE pbcCode,
a.PBC_PROD_ID pbcProdIdShow
from PBC_PRD_BASEINFO_END_SUB_DAT a
left join  b on a.Prod_Id = b.Prod_Id

LEFT JOIN(
SELECT
inside_prod_id,
pbc_code
FROM
pbc_prod_assetpool_code
WHERE
status='E'
AND code_type='01'
)t2 ON t2.inside_prod_id=b.PROD_ID



            #{items,jdbcType=VARCHAR}




        AND b.PROD_ID IN

            #{item,jdbcType=VARCHAR}




        and a.STATUS in

            #{item,jdbcType=VARCHAR}



        and trim(a.REGIST_SEQNO) in

            #{item,jdbcType=VARCHAR}



        and a.SEND_STATUS in

            #{item,jdbcType=VARCHAR}



        and a.SUBMIT_FEEDBACK_STATUS in

            #{item,jdbcType=VARCHAR}



        and b.OPERATE_MODE in

            #{item,jdbcType=VARCHAR}



        and b.IVSTORIENTATION in

            #{item,jdbcType=VARCHAR}



        and DATE_FORMAT(a.STATUS_DATE,'%Y-%m-%d') >= #{statusDateStart}


        and DATE_FORMAT(a.STATUS_DATE,'%Y-%m-%d') <= #{statusDateEnd}


        and DATE_FORMAT(a.SUBMIT_TIME,'%Y-%m-%d') >= #{submitTimeStart}


        and DATE_FORMAT(a.SUBMIT_TIME,'%Y-%m-%d') <= #{submitTimeEnd}


        and DATE_FORMAT(a.PBC_SUBMIT_DEADLINE,'%Y-%m-%d') >= #{pbcSubmitDeadlineDateStart}


        and DATE_FORMAT(a.PBC_SUBMIT_DEADLINE,'%Y-%m-%d') <= #{pbcSubmitDeadlineDateEnd}


        and DATE_FORMAT(a.MDATE,'%Y-%m-%d') >= #{mdateStart}


        and DATE_FORMAT(a.MDATE,'%Y-%m-%d') <= #{mdateEnd}


        and DATE_FORMAT(a.UPDATE_TIME,'%Y-%m-%d') = #{updateTime}



        and DATE_FORMAT(a.MDATE,'%Y-%m-%d') >= #{startDate}


        and DATE_FORMAT(a.MDATE,'%Y-%m-%d') <= #{endDate}



        and DAT_ZIP_CODE = #{zipCode}



ORDER BY A.PBC_SUBMIT_DEADLINE ASC, A.UPDATE_TIME DESC
